 if(!red){const time=g.time;ctx.globalAlpha=.4;for(let i=0;i<20;i++){const x=LEFT+(i*67)%430,y=100+((i*97-time*(8+i%4))%580+580)%580;ctx.fillStyle=r[2];ctx.beginPath();ctx.arc(x,y,1+i%2*.4,0,7);ctx.fill();}ctx.globalAlpha=1;}
 const frame=eq.frame||'frame_'+r[0];ctx.globalAlpha=.75;sprite(ctx,'sheet_frames',frame,-16,50,W+32,H-25);ctx.globalAlpha=1;
