  const labels={T:'✦',I:'❄',F:'♨',E:'ϟ',P:'◎',V:'↔',R:'↻',B:String(Math.max(0,Math.ceil(b.bombAt-g.time))),Y:'⚿'};if(labels[b.t])text(ctx,labels[b.t],b.x+b.w/2,b.y+16,13,b.t==='B'?'#ff415f':'#ffffff','center');
