 const baseState=g.frozen?'frozen':g.stunned?'stunned':e.laser?'laser':e.magnet?'magnet':g.shield||e.skill_shield?'shield':e.big_paddle?'wide':e.small_paddle?'narrow':'normal';const pscale=g.pw/(baseState==='wide'?262:baseState==='narrow'?122:190);const pwidth=288*pscale,pheight=96*pscale;
 sprite(ctx,eq.paddle?'sheet_skin_paddles':'sheet_paddle',eq.paddle||'paddle_'+baseState,g.px-g.pw/2,PY,g.pw,20);
 ctx.strokeStyle=e.laser?'#ff8b87':e.magnet?'#e2a5ff':'#b9faff';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(g.px-g.pw/2,PY);ctx.lineTo(g.px+g.pw/2,PY);ctx.stroke();
 if(g.shield||e.skill_shield){sprite(ctx,'sheet_gp_wide','shield_wall_'+Math.floor(g.time*8)%4,LEFT,PY+27,RIGHT-LEFT,24);}
