 for(const ball of g.balls){if(!red){ctx.strokeStyle=ballType==='normal'?'#adf7ff99':'#ffc477aa';ctx.lineWidth=3;ctx.beginPath();ball.trail.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineTo(ball.x,ball.y);ctx.stroke();}if(!sprite(ctx,eq.ball&&ballType==='normal'?'sheet_skin_balls':'sheet_balls',eq.ball&&ballType==='normal'?eq.ball:'ball_'+ballType,ball.x-9,ball.y-9,18,18)){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ball.x,ball.y,6,0,7);ctx.fill();}}
