 for(const f of fx){ctx.globalAlpha=Math.max(0,f.l);ctx.fillStyle=f.c;ctx.beginPath();ctx.moveTo(f.x,f.y-f.size);ctx.lineTo(f.x+f.size,f.y+f.size);ctx.lineTo(f.x-f.size,f.y+f.size);ctx.closePath();ctx.fill();}ctx.globalAlpha=1;
